using System.Data.SqlClient;
using Api.Models;

namespace Api.Repositories;

public class UserRepository
{
    private readonly string _connStr;

    public UserRepository(string connStr)
    {
        _connStr = connStr;
    }

    public async Task<User?> GetUserByIdAsync(int userId)
    {
        using var conn = new SqlConnection(_connStr);
        await conn.OpenAsync();
        var cmd = new SqlCommand(
            "SELECT id, name, email, active FROM users WHERE id = @id", conn);
        cmd.Parameters.AddWithValue("@id", userId);
        using var reader = await cmd.ExecuteReaderAsync();
        if (!await reader.ReadAsync()) return null;

        return new User
        {
            Id = reader.GetInt32(0),
            Name = reader.GetString(1),
            Email = reader.GetString(2),
            Active = reader.GetBoolean(3),
        };
    }

    public async Task UpdateUserAsync(int userId, string? name = null, string? email = null, bool? active = null)
    {
        using var conn = new SqlConnection(_connStr);
        await conn.OpenAsync();
        var updates = new List<string>();
        var cmd = new SqlCommand("UPDATE users SET " + string.Join(", ", updates) + " WHERE id = @id", conn);

        if (name != null)
        {
            updates.Add("name = @name");
            cmd.Parameters.AddWithValue("@name", name);
        }
        if (email != null)
        {
            updates.Add("email = @email");
            cmd.Parameters.AddWithValue("@email", email);
        }
        if (active != null)
        {
            updates.Add("active = @active");
            cmd.Parameters.AddWithValue("@active", active);
        }

        cmd.Parameters.AddWithValue("@id", userId);
        await cmd.ExecuteNonQueryAsync();
    }
}
